// New mechanisms share the existing progress and review pipeline, not answer screens.
export function newLabState(){return {bin:'',count:1,clues:[],subject:'',time:'',be:'',settings:{}};}
export function packPhrase(q,lab){const n=['','one','two','three','four','five'][lab.count];return n+' '+(lab.bin==='unit'?(lab.count===1?q.unit:q.unit+'s')+' of '+q.noun:(lab.count===1?q.noun:q.plural));}
export function labAnswer(q,lab){if(q.type==='pack')return lab.bin+'|'+lab.count;if(q.type==='mirror')return [lab.subject,lab.time,lab.be].join('|');if(q.type==='director')return JSON.stringify(Object.fromEntries(Object.keys(q.axes).map(k=>[k,lab.settings[k]])));return '';}
export function portraitSVG(person){const color=person.color==='red'?'#c98168':'#739eaf',scale=person.size==='small'?.77:1;return `<svg viewBox="0 0 160 175" aria-hidden="true"><ellipse cx="80" cy="158" rx="48" ry="7" fill="#d9dfcd"/><g transform="translate(80 153) scale(${scale}) translate(-80 -153)"><path d="M53 104Q80 88 107 104L119 151H41Z" fill="${color}"/><path d="m45 70 5-45 28 19 28-19 9 45q-6 41-35 41T45 70" fill="#e5a26e"/><path d="m48 76 32 12 32-12q-9 28-32 28T48 76" fill="#fff0d2"/><circle cx="67" cy="72" r="3" fill="#435244"/><circle cx="93" cy="72" r="3" fill="#435244"/><path d="m75 87 5 5 5-5" fill="#435244"/>${person.prop==='hat'?'<path d="M40 42h80v9H40zm15 0 6-28h38l7 28" fill="#d8b46f"/><path d="M57 34h46" stroke="#857b56" stroke-width="7"/>':'<path d="m55 112 25 4 25-4v30l-25 4-25-4Z" fill="#f4e1a3" stroke="#b69b69" stroke-width="2"/><path d="M80 116v30" stroke="#b69b69" stroke-width="2"/>'}</g></svg>`;}
export function renderPlayground(q,session,art,esc){const l=session.lab,locked=!!session.feedback||session.answered,off=locked?'disabled':'';let body='';
if(q.type==='pack'){body=`<div class="pack-table"><div class="cargo-row">${Array.from({length:l.count},()=>`<span class="cargo">${l.bin==='unit'?(q.unit==='cup'?'☕':q.unit==='bowl'?'🥣':q.unit==='slice'?'🍞':'🧺'):(q.icon==='apple'?'🍎':q.icon==='box'?'📦':q.icon==='water'?'💧':q.icon==='bread'?'🍞':'🍚')}</span>`).join('')}</div><div class="bag-choices"><button data-action="lab-bin" data-value="direct" aria-pressed="${l.bin==='direct'}" class="bag-choice ${l.bin==='direct'?'selected':''}" ${off}><span class="bag-handle"></span><strong>直接数物品</strong><small>one apple · two apples</small><span class="bag-pocket">1 · 2 · 3</span></button><button data-action="lab-bin" data-value="unit" aria-pressed="${l.bin==='unit'}" class="bag-choice ${l.bin==='unit'?'selected':''}" ${off}><span class="bag-handle"></span><strong>借助单位装</strong><small>a cup of water</small><span class="bag-pocket">杯 · 碗 · 片</span></button></div><div class="quantity"><span>装多少？</span><button data-action="lab-count" data-value="-1" aria-label="数量减一" ${locked||l.count===1?'disabled':''}>−</button><output aria-live="polite">${l.count}</output><button data-action="lab-count" data-value="1" aria-label="数量加一" ${locked||l.count===5?'disabled':''}>＋</button></div><div class="lab-preview"><small>试装表达 · 确认后看解释</small><p lang="en">${l.bin?esc(packPhrase(q,l)):'先选一只背包'}</p></div><button class="primary" data-action="check-lab" ${locked||!l.bin?'disabled':''}>装包完成，检查一下 ✓</button></div>`;}
if(q.type==='portrait'){const active=l.clues.map(i=>q.clues[i]);const count=q.characters.filter(p=>active.every(([k,v])=>p[k]===v)).length;body=`<div class="portrait-studio"><div class="clue-desk"><span>点亮线索，看看谁留下来</span>${q.clues.map((c,i)=>`<button data-action="lab-clue" data-index="${i}" aria-pressed="${l.clues.includes(i)}" class="clue ${l.clues.includes(i)?'selected':''}" ${off}>${l.clues.includes(i)?'✓':'＋'} ${esc(c[2])}</button>`).join('')}</div><p class="candidate-count" aria-live="polite">${active.length?'线索交集':'还没筛选'} · 当前 ${count} 位候选人</p><div class="portrait-grid">${q.characters.map(p=>{const fits=active.every(([k,v])=>p[k]===v),label=p.id+'号 · '+(p.size==='small'?'小个子':'大个子')+' · '+(p.color==='red'?'红衣服':'蓝衣服')+' · '+(p.prop==='hat'?'戴帽子':'拿着书');return `<button data-action="answer" data-answer="${p.id}" class="portrait-candidate ${fits?'':'ruled-out'} ${session.answered&&p.id===q.answer?'delivered':''}" ${locked||!fits?'disabled':''} aria-label="${label}">${portraitSVG(p)}<span>${p.id} 号朋友</span><small>${esc(label.slice(5))}</small>${!fits?'<i>线索不符合</i>':''}</button>`;}).join('')}</div><p class="interaction-tip">可以再次点击线索撤回筛选。线索是题目的一部分，不算额外提示。</p></div>`;}
if(q.type==='mirror'){body=`<div class="mirror-room"><div class="mirror-glass ${l.time==='past'?'yesterday':''}"><div class="mirror-people">${Array.from({length:['They','We'].includes(l.subject)?3:1},(_,i)=>`<div>${portraitSVG({size:'small',color:i%2?'blue':'red',prop:'hat'})}</div>`).join('')}</div><p lang="en">${esc(l.subject||'谁')} <strong>${esc(l.be||'___')}</strong> ${esc(q.tail)}.</p><span>${l.time==='past'?'◷ 昨天的回忆':l.time==='now'?'● 现在的镜子':'先选时间'}</span></div><div class="mirror-controls"><fieldset><legend>① 人物</legend>${['I','She','They','You','Mia','We'].map(p=>`<button data-action="lab-person" data-value="${p}" aria-pressed="${l.subject===p}" class="${l.subject===p?'selected':''}" ${off}>${p}</button>`).join('')}</fieldset><fieldset><legend>② 时间</legend>${[['now','现在'],['past','昨天']].map(([v,t])=>`<button data-action="lab-time" data-value="${v}" aria-pressed="${l.time===v}" class="${l.time===v?'selected':''}" ${off}>${t}</button>`).join('')}</fieldset><fieldset><legend>③ 接上 be</legend>${['am','is','are','was','were'].map(v=>`<button data-action="lab-be" data-value="${v}" aria-pressed="${l.be===v}" class="${l.be===v?'selected':''}" ${off}>${v}</button>`).join('')}</fieldset></div><p class="interaction-tip">镜中是你正在试接的句子，完成后检查人物、时间与 be 是否都匹配任务。</p><button class="primary" data-action="check-lab" ${locked||!l.subject||!l.time||!l.be?'disabled':''}>连接镜子，检查搭档 ✓</button></div>`;}
if(q.type==='director'){const s=l.settings,filled=Object.keys(q.axes).every(k=>!!s[k]),sentence=q.frame.replace(/\{(\w+)\}/g,(_,k)=>s[k]||'___'),freq=s.frequency==='always'?5:s.frequency==='sometimes'?2:s.frequency==='never'?0:null;body=`<div class="director-room"><div class="movie-stage ${q.axes.degree?'degree-scene':''} ${s.place==='at home'?'at-home':'garden'} ${s.time==='tomorrow'?'tomorrow':''} ${s.frequency==='never'?'never':''}" style="--walk-time:${s.manner==='quickly'?'1.5s':'5s'}"><span class="movie-sun">${s.time==='tomorrow'?'明天':'☀'}</span><div class="movie-scenery">${art(s.place==='at home'?'house':'flower')}</div><div class="walking-fox">${portraitSVG({size:'small',color:'red',prop:'hat'})}</div>${s.degree?`<span class="tired-meter" aria-label="疲倦程度">${s.degree==='very'?'Z z z z':'z'}<i style="width:${s.degree==='very'?88:25}%"></i></span>`:''}${freq!==null?`<div class="frequency-dots" aria-label="频率示意，非精确比例">${Array.from({length:5},(_,i)=>`<i class="${i<freq?'on':''}"></i>`).join('')}<span>${s.frequency==='never'?'从不出发':s.frequency==='always'?'每次出发':'有时出发'}</span></div>`:''}</div><div class="director-controls">${Object.entries(q.axes).map(([axis,opts])=>`<fieldset><legend>${({manner:'速度与方式',place:'地点',frequency:'频率',time:'故事时间',degree:'程度'})[axis]}</legend>${opts.map(([v,t])=>`<button data-action="lab-direct" data-axis="${axis}" data-value="${v}" aria-pressed="${s[axis]===v}" class="${s[axis]===v?'selected':''}" ${off}><strong>${esc(v)}</strong><small>${esc(t)}</small></button>`).join('')}</fieldset>`).join('')}</div><div class="lab-preview"><small>正在试拍的故事</small><p lang="en">${esc(sentence)}</p></div><button class="primary" data-action="check-lab" ${locked||!filled?'disabled':''}>这个镜头符合任务 ✓</button></div>`;}
return `<div id="playground-host" class="playground playground-${q.type} ${session.answered?'lab-success':''}">${body}</div>`;}
